def rule(ctx):
    if ctx.robots:
        total_wt = 0
        n_wt = 0
        for r in ctx.robots:
            t = ctx.types[r.type]
            if t is not None:
                total_wt += t.get("work_time", 0)
                n_wt += 1
        if n_wt > 0 and total_wt > 0:
            avg_wt = total_wt / n_wt
        else:
            avg_wt = 10.0
    else:
        avg_wt = 10.0
    if avg_wt <= 0:
        avg_wt = 10.0

    def workload(r):
        return r.count + r.hours / avg_wt

    tight = ctx.capacity < ctx.remaining

    if tight:
        def avail_key(r):
            return (-r.duties_left, r.first_maint is not None, workload(r), -r.ready, r.idx)
    else:
        def avail_key(r):
            return (r.first_maint is not None, workload(r), -r.duties_left, -r.ready, r.idx)

    avail = sorted(ctx.available, key=avail_key)
    actions = [("reuse", r) for r in avail]

    def new_key(k):
        t = ctx.types[k]
        if t is None or ctx.left[k] <= 0:
            return (1, 0.0, 0, 0, 0, 0, k)
        work = t.get("work_time", 0)
