        maint = t.get("maintenance_time", 0)
        sw = t.get("single_work_time", 0)
        cmw = t.get("continue_max_work", 0)
        if sw > 0:
            duties = cmw / sw
        else:
            duties = 1.0
        if duties < 1.0:
            duties = 1.0
        cycle = work + out + ret + charge
        if cycle <= 0:
            cycle = 1.0
        fit = ctx.remaining / cycle
        useful = duties if duties < fit else fit
        if useful < 0.1:
            useful = 0.1
        maint_cost = maint if fit >= duties else 0
        total_time = useful * cycle + maint_cost
        eff = (useful * work) / total_time if total_time > 0 else 0.0
        cannot_fit = 1 if ctx.remaining < cycle else 0
        overshoot = work - ctx.remaining if work > ctx.remaining else 0
        gene = 0 if k == ctx.gene_type else 1
        return (cannot_fit, -eff, overshoot, -ctx.left[k], gene, -work, k)

    new_types = [k for k in range(len(ctx.types)) if ctx.types[k] is not None and ctx.left[k] > 0]
    new_types.sort(key=new_key)
    actions.extend(("new", k) for k in new_types)
    return actions
