        t = ctx.types[r.type]
        wt = t.get("work_time", 0) if t is not None else 0
        over = r.count - cap
        if over < 0:
            over = 0
        count_gap = r.count - min_count
        if count_gap < 0:
            count_gap = 0
        hours_after = r.hours + wt
        return (over, count_gap, r.duties_left, hours_after, r.ready, r.idx)

    avail = sorted(ctx.available, key=avail_key)
    actions = [("reuse", r) for r in avail]

    def new_key(k):
        t = ctx.types[k]
        if t is None or ctx.left[k] <= 0:
            return (1, 0, 0, 0, 0, 0, 0, 0, k)
        work = t.get("work_time", 0)
