        cmw = t.get("continue_max_work", 0)
        if sw > 0:
            duties = cmw / sw
        else:
            duties = 0
        cycle = work + out + ret + charge
        total = duties * cycle + maint
        if total > 0:
            eff = (duties * work) / total
        else:
            eff = 0
        coverage = duties * work
        shortfall = ctx.remaining - coverage
        if shortfall < 0:
            shortfall = 0
        overshoot = work - ctx.remaining
        if overshoot < 0:
            overshoot = 0
        gene_penalty = 0 if k == ctx.gene_type else 1
        return (0, -eff, shortfall, overshoot, -coverage, maint, -ctx.left[k], gene_penalty, k)

    new_types = [k for k in range(len(ctx.types)) if ctx.types[k] is not None and ctx.left[k] > 0]
    new_types.sort(key=new_key)
    actions.extend(("new", k) for k in new_types)

    if not actions:
