        avg_work = sum(work_hours(r) for r in robots) / float(n_robots)
    else:
        min_count = 0
        min_hours = 0.0
        avg_work = 10.0

    if avg_work < 1.0:
        avg_work = 1.0

    remaining = ctx.remaining
    if remaining < 1.0:
        remaining = 1.0

    if remaining > 20.0 * avg_work:
        fair_count_gap = 2
        fair_hour_gap = 2.2 * avg_work
        phase_strength = 0.45
    elif remaining > 8.0 * avg_work:
        fair_count_gap = 1
        fair_hour_gap = 1.3 * avg_work
        phase_strength = 0.30
    else:
        fair_count_gap = 0
        fair_hour_gap = 0.6 * avg_work
        phase_strength = 0.15

    t = ctx.t

