{Rank available robots by a staged score that first limits duty-count excess, then favors low remaining maintenance duties and balanced duty/hours with idle-time tie-breaking, before ordering feasible new robot types by horizon-fit overshoot, work efficiency, maintenance overhead, and gene-type preference.}
```python
def rule(ctx):
    def work_time(r):
        t = ctx.types[r.type]
        if t is None:
            return 0
        return t.get("work_time", 0)

    robots = ctx.robots
    n = len(robots)
    if n:
        min_count = min(r.count for r in robots)
        total_count = sum(r.count for r in robots)
        avg_count = total_count / float(n)
        total_hours = sum(r.hours for r in robots)
        avg_hours = total_hours / float(n)
    else:
        min_count = 0
        avg_count = 0.0
        avg_hours = 0.0

    cap = min_count + 2
    if n > 6:
        cap = min_count + 1

    def avail_key(r):
        t = ctx.types[r.type]
        wt = t.get("work_time", 0) if t is not None else 0
        over_abs = r.count - cap
        if over_abs < 0:
            over_abs = 0
        count_dev = r.count - avg_count
        if count_dev < 0:
            count_dev = -count_dev
        hours_dev = (r.hours + wt) - avg_hours
        if hours_dev < 0:
            hours_dev = -hours_dev
        return (over_abs, r.duties_left, count_dev, r.count, hours_dev, r.ready, r.idx)

    avail = sorted(ctx.available, key=avail_key)
    actions = [("reuse", r) for r in avail]

    rem = ctx.remaining

    def new_key(k):
        t = ctx.types[k]
        if t is None or ctx.left[k] <= 0:
            return (1, 0, 0, 0, 0, 0, 0, k)
        work = t.get("work_time", 0)
        out = t.get("out_travel_time", 0)
        ret = t.get("return_travel_time", 0)
        charge = t.get("charge_time", 0)
        maint = t.get("maintenance_time", 0)
        sw = t.get("single_work_time", 0)
        cmw = t.get("continue_max_work", 0)
        if sw > 0:
            duties = cmw / float(sw)
        else:
            duties = 0.0
        busy = work + out + ret + charge
        total = duties * busy + maint
        if total > 0:
            eff = (duties * work) / total
        else:
            eff = 0.0
        time_to_maint = duties * busy if busy > 0 else 0.0
        if time_to_maint >= rem:
            horizon_eff = work / float(busy) if busy > 0 else 0.0
        else:
            horizon_eff = eff
        overshoot = work - rem
        if overshoot < 0:
            overshoot = 0
        gene_penalty = 0 if k == ctx.gene_type else 1
        return (overshoot, -horizon_eff, -work if work <= rem else 0, maint, gene_penalty, -ctx.left[k], k)

    new_types = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            new_types.append(k)
    new_types.sort(key=new_key)
    actions.extend(("new", k) for k in new_types)
    return actions
```

{Use a rolling coverage-margin score that ranks available robots by blended load deficit, maintenance-buffer loss, and readiness rotation, then ranks new types by sustained horizon coverage with existing-type and gene-preference tie-breaks.}
```python
def rule(ctx):
    types = ctx.types
    remaining = float(ctx.remaining)
    if remaining < 1.0:
        remaining = 1.0
    t = float(ctx.t)
    robots = ctx.robots
    n_robots = len(robots)

    def work_of(r):
        th = types[r.type]
        if th is None:
            return 10.0
        w = float(th.get("work_time", 0.0) or 0.0)
        if w <= 0.0:
            w = float(th.get("single_work_time", 0.0) or 0.0)
        if w <= 0.0:
            w = 10.0
        return w

    if n_robots:
        avg_count = sum(r.count for r in robots) / float(n_robots)
        avg_hours = sum(r.hours for r in robots) / float(n_robots)
        avg_work = sum(work_of(r) for r in robots) / float(n_robots)
    else:
        avg_count = 0.0
        avg_hours = 0.0
        avg_work = 10.0
        total_work = 0.0
        n_work = 0
        for th in types:
            if th is not None:
                w = float(th.get("work_time", 0.0) or 0.0)
                if w <= 0.0:
                    w = float(th.get("single_work_time", 0.0) or 0.0)
                if w > 0.0:
                    total_work += w
                    n_work += 1
        if n_work > 0:
            avg_work = total_work / float(n_work)

    if avg_work <= 0.0:
        avg_work = 10.0

    cap = float(ctx.capacity) if n_robots else 0.0
    cap_ratio = cap / remaining if remaining > 0.0 else 1.0
    tight = cap_ratio < 1.05

    n_types = len(types)
    type_flex = [0.0] * n_types
    for k in range(n_types):
        if types[k] is not None and k < len(ctx.left):
            type_flex[k] += float(ctx.left[k]) * 0.35
    for r in robots:
        if 0 <= r.type < n_types:
            dl = float(r.duties_left)
            if dl < 1.0:
                dl = 1.0
            type_flex[r.type] += dl * 0.20 + 0.10

    def robot_score(r):
        th = types[r.type]
        w = work_of(r)
        out = 0.0
        ret = 0.0
        charge = 0.0
        maint = 0.0
        if th is not None:
            out = float(th.get("out_travel_time", 0.0) or 0.0)
            ret = float(th.get("return_travel_time", 0.0) or 0.0)
            charge = float(th.get("charge_time", 0.0) or 0.0)
            maint = float(th.get("maintenance_time", 0.0) or 0.0)

        dl = float(r.duties_left)
        trigger = dl <= 1.0
        cycle_ready = w + out + ret + (maint if trigger else charge)

        if trigger:
            if remaining > maint + 1.4 * avg_work:
                maint_term = -0.20 * maint / (remaining + 1.0)
            else:
                maint_term = 0.60 + 1.8 * maint / (remaining + 1.0)
        else:
            maint_term = 0.0

        load = (float(r.count) - avg_count) + 0.55 * (float(r.hours) - avg_hours) / avg_work

        if tight:
            buffer_term = -0.10 * dl
        else:
            buffer_term = 0.075 * dl

        ready_term = (0.16 if tight else 0.035) * cycle_ready / (w + out + ret + charge + maint + 1.0)

        if r.last_end is None:
            idle_term = -0.06
        else:
            idle = t - float(r.last_end)
            if idle < 0.0:
                idle = 0.0
            idle_unit = w + out + ret + charge + 1.0
            idle_term = -0.018 * min(idle, 4.0 * idle_unit) / idle_unit

        flex_term = 0.04 / (1.0 + (type_flex[r.type] if 0 <= r.type < n_types else 1.0))

        return (
            load + maint_term + buffer_term + ready_term + idle_term + flex_term,
            r.count,
            -r.duties_left,
            r.ready,
            r.idx
        )

    available_sorted = sorted(ctx.available, key=robot_score)
    actions = [("reuse", r) for r in available_sorted]

    existing = [False] * n_types
    for r in robots:
        if 0 <= r.type < n_types:
            existing[r.type] = True

    valid_new = []
    for k in range(n_types):
        if types[k] is not None and k < len(ctx.left) and ctx.left[k] > 0:
            valid_new.append(k)

    def new_score(k):
        th = types[k]
        w = float(th.get("work_time", 0.0) or 0.0)
        if w <= 0.0:
            w = float(th.get("single_work_time", 0.0) or 0.0)
        if w <= 0.0:
            w = avg_work

        out = float(th.get("out_travel_time", 0.0) or 0.0)
        ret = float(th.get("return_travel_time", 0.0) or 0.0)
        charge = float(th.get("charge_time", 0.0) or 0.0)
        maint = float(th.get("maintenance_time", 0.0) or 0.0)
        sw = float(th.get("single_work_time", 0.0) or 0.0)
        cmw = float(th.get("continue_max_work", 0.0) or 0.0)

        if sw > 0.0 and cmw > 0.0:
            duty_cap = cmw / sw
        else:
            duty_cap = 1.0
        if duty_cap < 1.0:
            duty_cap = 1.0

        cycle = w + out + ret + charge
        if cycle <= 0.0:
            cycle = w + 1.0

        sustain = (duty_cap * w) / (duty_cap * cycle + maint + 1.0)

        base_w = max(w, 0.1)
        rem_mod = remaining % base_w
        alt = base_w - rem_mod
        waste = rem_mod if rem_mod < alt else alt
        fit = waste / base_w

        reuse_penalty = 0 if existing[k] else 1
        gene_penalty = 0 if k == ctx.gene_type else 1
        bridge = out + w + ret + charge * 0.25

        if remaining < 3.0 * avg_work:
            return (0, -sustain * 0.5, bridge, reuse_penalty, gene_penalty, fit, maint, k)
        return (0, -sustain, fit, reuse_penalty, gene_penalty, bridge, maint, -ctx.left[k], k)

    valid_new.sort(key=new_score)
    actions.extend(("new", k) for k in valid_new)
    return actions
```

