```python
def rule(ctx):
    def robot_key(r):
        return (r.count, r.hours, -r.duties_left, -r.budget, r.idx)
    av = sorted(ctx.available, key=robot_key)
    actions = [("reuse", r) for r in av]

    valid = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            valid.append(k)

    def type_score(k):
        t = ctx.types[k]
        n = t['continue_max_work'] / max(t['single_work_time'], 1e-9)
        if n < 1.0:
            n = 1.0
        productive = n * t['work_time']
        cycle_time = n * (t['work_time'] + t['out_travel_time'] + t['return_travel_time'] + t['charge_time']) + t['maintenance_time']
        s = productive / max(cycle_time, 1e-9)
        w = t['work_time']
        if ctx.remaining > 0 and w > ctx.remaining:
            s *= ctx.remaining / w
        return s

    new_order = []
    if ctx.gene_type in valid:
        new_order.append(ctx.gene_type)
        valid.remove(ctx.gene_type)
    valid.sort(key=type_score, reverse=True)
    new_order.extend(valid)
    actions.extend(("new", k) for k in new_order)

    if not new_order and ctx.gene_type is not None:
        actions.append(("new", ctx.gene_type))

    return actions
