{Use a fairness-and-maintenance-aware rule that ranks available robots by fewest duties, normalized duty hours, most remaining pre-maintenance budget, and earliest readiness, then orders new-robot types with the genome type first and other types by remaining slots, capacity need, and maintenance/charge overhead.}
```python
def rule(ctx):
    actions = []

    def reuse_score(r):
        typ = ctx.types[r.type] if r.type < len(ctx.types) else None
        duty = (typ.get("work_time", 1) if typ is not None else 1) or 1
        return (r.count, r.hours / duty, -r.duties_left, r.ready, r.idx)

    for r in sorted(ctx.available, key=reuse_score):
        actions.append(("reuse", r))

    candidates = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            candidates.append(k)

    need_new = (ctx.capacity < ctx.remaining) if candidates else True

    def type_score(k):
        t = ctx.types[k]
        single = t.get("single_work_time", 1) or 1
        cont = t.get("continue_max_work", 1) or 1
        maint = t.get("maintenance_time", 0) or 0
        charge = t.get("charge_time", 0) or 0
        work = t.get("work_time", 0) or 0
        left = ctx.left[k]
        if need_new:
            return (maint + charge, -cont / single, -left, -work, k)
        return (charge + 0.25 * maint, -left, -cont / single, -work, k)

    if ctx.gene_type in candidates:
        actions.append(("new", ctx.gene_type))

    for k in sorted(candidates, key=type_score):
        if k != ctx.gene_type:
            actions.append(("new", k))

    if not candidates:
        actions.append(("new", ctx.gene_type))

    return actions
